package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

import java.time.LocalDate;

/** customer-code-city: Change the customerCode format to '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased... */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreCustomerCodeHasCityPrefix() throws Exception {
		int id = createOwnerOk(ownerNode());
		JsonNode n = fetchOwner(id);
		assertTrue(n.get("customerCode").asText().matches("[A-Z]{3}-[A-Z]{3}-\\d{4}")); // <CITY3>-<LAST3>-<NNNN>
	}

	@Test
	void customerCodeSequenceIsPerCity() throws Exception {
		String city = "Zelda" + letters(seq());
		fillCity(city, 2);
		ObjectNode o = ownerNode();
		o.put("city", city.toUpperCase());
		o.put("lastName", "Franklin");
		JsonNode n = fetchOwner(createOwnerOk(o));
		assertEquals("ZEL-FRA-0003", n.get("customerCode").asText());

		ObjectNode other = ownerNode();
		other.put("lastName", "Davis");
		JsonNode m = fetchOwner(createOwnerOk(other));
		assertEquals("TOW-DAV-0001", m.get("customerCode").asText());
	}

	@Test
	void membershipNumberUsesNewCustomerCode() throws Exception {
		JsonNode n = fetchOwner(createOwnerOk(ownerNode()));
		String code = n.get("customerCode").asText();
		int yy = Math.floorMod(LocalDate.parse(n.get("registrationDate").asText()).getYear(), 100);
		assertEquals(String.format("%s-M%02d", code, yy), n.get("membershipNumber").asText());
		assertTrue(n.get("membershipNumber").asText().matches("[A-Z]{3}-[A-Z]{3}-\\d{4}-M\\d{2}"));
	}
}
EOF
